function hasThreeOddsInRow(nums: number[]): boolean {
  const odd = (x: number) => x % 2 !== 0;
  for (let i = 0; i + 2 < nums.length; i++) {
    if (odd(nums[i]) && odd(nums[i + 1]) && odd(nums[i + 2])) return true;
  }
  return false;
}

